export async function logIn(page, username, password) {
    await page.locator("#username").fill(username);
    await page.locator("#password").fill(password);
    await page.getByRole("button", { name: "Login" }).click();
    await page.getByRole("link", { name: "I'm already set up, just bring me to the homepage" }).click();
}

export async function openSettingsMenu(page) {
    await page.getByText("Settings").click();
}

export async function toggleTheme(page, themeLabel) {
    await page.getByText(themeLabel).click();
}
